        let rotation = Quat::from_rotation_y(view.yaw);
        let input_turn = std::mem::take(&mut view.pending_yaw_delta);
        if input_turn.abs() > 0.000001 || !transform.rotation.abs_diff_eq(rotation, 0.000001) {
            let turn = if input_turn != 0.0 {
